let flip = 0;
let font;
let pg;
let pgShader;

let projector;
let projectionShader;
let mMatrix = new p5.Matrix();

function preload() {
	font = loadFont('https://openprocessing.org/sketch/1245784/files/Roboto-Black.ttf');
}

function setup() {
	createCanvas(1112, 834, WEBGL);
	noStroke();
	pixelDensity(1);

	pg = createGraphics(width, height, WEBGL);
	pg.noStroke();
	pgShader = pg.createShader(pgVert, pgFrag);
	pg.shader(pgShader);
	pgShader.setUniform('uSeed', random(15, 30));
	pgShader.setUniform('uResolution', [width, height]);

	projector = new p5.Camera(this._renderer);
	projector.camera(0, 0, (height/4.0) / tan(PI*30.0 / 180.0), 0, 0, 0, 0, 1, 0);
	projector.perspective(PI*2/3, 1.0, 0.1, 100);

	projectionShader = createShader(lightingShader + projectionVert, projectionFrag);
	shader(projectionShader);
	projectionShader.setUniform('uTexPMatrix', projector.projMatrix.mat4);
	projectionShader.setUniform('uTexVMatrix', projector.cameraMatrix.mat4);
}

function draw() {
	if (flip == 1) scale(1, -1);
	pgShader.setUniform('uTime', millis() / 1000.0);
	pg.rect(-width / 2, -height / 2, width, height);
	projectionShader.setUniform('uTexture', pg);

	background(0);
	ambientLight(230);
	pointLight(80, 80, 80, 0, 0, (height/4.0) / tan(PI*30.0 / 180.0));

	mMatrix = p5.Matrix.identity();
	mMatrix.scale(160, 160, 200);
	projectionShader.setUniform('uModelMatrix', mMatrix.mat4);
	//text3D(font, 'backslant', 160, 120, 20);

	mMatrix = p5.Matrix.identity();
	mMatrix.scale(width*2, height*2, 1);
	projectionShader.setUniform('uModelMatrix', mMatrix.mat4);
	push();
	plane(width*2, height*2, 1);
	pop();
}

function text3D(font, text, size, depth, divisions, horizontal_align, vertical_align) {
	if (typeof text !== 'string') {
		text = str(text);
	}

	if (typeof horizontal_align === 'undefined') {
		horizontal_align = CENTER;
	}
	if (typeof vertical_align === 'undefined') {
		vertical_align = CENTER;
	}

	const gId = `${font}|${text}|${divisions}`;

	if (!this._renderer.geometryInHash(gId)) {
		const textGeom = new p5.Geometry();

		const vertices = textToVertices(font, text, 1, divisions, horizontal_align, vertical_align);
		const z1 = new p5.Vector(0, 0, 0.5);
		const z2 = new p5.Vector(0, 0, -0.5);
		let id = 0;

		// 表面・裏面
		let tesselateVertices = this._renderer._triangulate(verticesToArray(vertices));
		tesselateVertices = arrayToVertices(tesselateVertices);
		tesselateVertices = verticesFilter(tesselateVertices);

		for (let i = 0; i < tesselateVertices.length; i++) {
			textGeom.vertices.push(p5.Vector.add(tesselateVertices[i], z1));
		}
		for (let i = 0; i < tesselateVertices.length; i++) {
			textGeom.vertices.push(p5.Vector.add(tesselateVertices[tesselateVertices.length - (i + 1)], z2));
		}

		for (let i = 0; i < tesselateVertices.length * 2; i += 3) {
			textGeom.faces.push([i, i + 1, i + 2]);
		}

		id = tesselateVertices.length * 2;

		// 側面
		for (const vers of vertices) {
			for (const ver of vers) {
				textGeom.vertices.push(p5.Vector.add(ver, z1));
				textGeom.vertices.push(p5.Vector.add(ver, z2));
			}

			let len = vers.length * 2;
			for (let i = 0; i < len; i += 2) {
				textGeom.faces.push([id + i, id + i + 1, id + (i + 2) % len]);
				textGeom.faces.push([id + (i + 3) % len, id + (i + 2) % len, id + i + 1]);
			}

			id += len;
		}

		// 法線・辺計算
		textGeom.computeNormals();
		textGeom._makeTriangleEdges()._edgesToVertices();

		// バッファ作成
		this._renderer.createBuffers(gId, textGeom);
	}

	// 描画
	this._renderer.drawBuffersScaled(gId, size, size, depth);
}


function textToVertices(font, text, size, divisions, horizontal_align, vertical_align) {
	const bounds = font.textBounds(text, 0, 0, size);

	let x, y;
	switch (horizontal_align) {
		case RIGHT:
			x = -bounds.x - bounds.w;
			break;
		case CENTER:
			x = -bounds.x - bounds.w / 2;
			break;
		case LEFT:
			x = -bounds.x;
			break;
	}
	switch (vertical_align) {
		case TOP:
			y = -bounds.y - bounds.h;
			break;
		case CENTER:
			y = -bounds.y - bounds.h / 2;
			break;
		case BOTTOM:
			y = -bounds.y;
			break;
	}

	const pdata = font.font.getPath(text, x, y, size).commands;

	let all_vertices = [];
	var vertices = [];
	let current_pos = new p5.Vector();

	for (const cmd of pdata) {
		if (cmd.type === 'M') {
			vertices = [];
			current_pos.set(cmd.x, cmd.y, 0.0);
			vertices.push(current_pos.copy());
		} else if (cmd.type === 'L') {
			if (current_pos.x == cmd.x && current_pos.y == cmd.y) continue;
			current_pos.set(cmd.x, cmd.y, 0.0);
			vertices.push(current_pos.copy());
		} else if (cmd.type === 'C') {
			for (let i = 1; i < divisions; i++) {
				var x = bezierPoint(current_pos.x, cmd.x1, cmd.x2, cmd.x, i / divisions);
				const y = bezierPoint(current_pos.y, cmd.y1, cmd.y2, cmd.y, i / divisions);
				vertices.push(new p5.Vector(x, y, 0.0));
			}
			current_pos.set(cmd.x, cmd.y, 0.0);
			vertices.push(current_pos.copy());
		} else if (cmd.type === 'Q') {
			for (let i = 1; i < divisions; i++) {
				var x = bezierPoint(current_pos.x, cmd.x1, cmd.x1, cmd.x, i / divisions);
				var y = bezierPoint(current_pos.y, cmd.y1, cmd.y1, cmd.y, i / divisions);
				vertices.push(new p5.Vector(x, y, 0.0));
			}
			current_pos.set(cmd.x, cmd.y, 0.0);
			vertices.push(current_pos.copy());
		} else if (cmd.type === 'Z') {
			vertices.pop();
			all_vertices.push(vertices);
		}
	}

	return all_vertices;
}


function verticesToArray(vertices) {
	let all_array = [];

	for (let vers of vertices) {
		let array = [];
		for (let ver of vers) {
			array = array.concat(ver.x, ver.y, ver.z);
		}
		all_array.push(array);
	}

	return all_array;
}


function arrayToVertices(array) {
	var vertices = [];

	for (let i = 0; i < array.length; i += 3) {
		vertices.push(new p5.Vector(array[i], array[i + 1], array[i + 2]));
	}

	return vertices;
}


function verticesFilter(vertices) {
	let filtered = [];
	for (let i = 0; i < vertices.length; i += 3) {
		let ba = p5.Vector.sub(vertices[i + 1], vertices[i]);
		let bc = p5.Vector.sub(vertices[i + 1], vertices[i + 2]);
		let cross = p5.Vector.cross(ba, bc);

		if (p5.Vector.mag(cross) != 0) {
			filtered.push(vertices[i], vertices[i + 1], vertices[i + 2]);
		}
	}

	return filtered;
}

// === Tab: pgShader ===
let pgVert = `

precision highp float;

attribute vec3 aPosition;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;

void main(void) {
  vec4 positionVec4 = vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
}

`;



let pgFrag = `

precision highp float;

uniform float uSeed;
uniform float uTime;
uniform vec2 uResolution;

void main(void) {
	vec2 p = gl_FragCoord.xy / uResolution - 0.5;

	float x = cos(p.x * uSeed * sin(cos(uSeed) * uTime));
	float y = sin(p.y * uSeed * sin(sin(uSeed) * uTime));

	for (int i=0; i<10; i++) {
		x = cos(x + 0.5 * y);
		y = cos(0.4 * x + y);
	}

	float len = length(vec2(x, y) - p);

	gl_FragColor = vec4(.5, 0.8 + 0.2 * cos(len * 61.4338 + uTime * 1.1), 0.8 + 0.1 * sin(len * 43.3247 - uTime * 0.9), 1.0);
}

`;

// === Tab: projectionShader ===
// p5.js default lighting shader
let lightingShader = `
precision highp float;
precision highp int;

uniform mat4 uViewMatrix;

uniform bool uUseLighting;

uniform int uAmbientLightCount;
uniform vec3 uAmbientColor[5];

uniform int uDirectionalLightCount;
uniform vec3 uLightingDirection[5];
uniform vec3 uDirectionalDiffuseColors[5];
uniform vec3 uDirectionalSpecularColors[5];

uniform int uPointLightCount;
uniform vec3 uPointLightLocation[5];
uniform vec3 uPointLightDiffuseColors[5];	
uniform vec3 uPointLightSpecularColors[5];

uniform int uSpotLightCount;
uniform float uSpotLightAngle[5];
uniform float uSpotLightConc[5];
uniform vec3 uSpotLightDiffuseColors[5];
uniform vec3 uSpotLightSpecularColors[5];
uniform vec3 uSpotLightLocation[5];
uniform vec3 uSpotLightDirection[5];

uniform bool uSpecular;
uniform float uShininess;

uniform float uConstantAttenuation;
uniform float uLinearAttenuation;
uniform float uQuadraticAttenuation;

const float specularFactor = 2.0;
const float diffuseFactor = 0.73;

struct LightResult {
  float specular;
  float diffuse;
};

float _phongSpecular(
  vec3 lightDirection,
  vec3 viewDirection,
  vec3 surfaceNormal,
  float shininess) {

  vec3 R = reflect(lightDirection, surfaceNormal);
  return pow(max(0.0, dot(R, viewDirection)), shininess);
}

float _lambertDiffuse(vec3 lightDirection, vec3 surfaceNormal) {
  return max(0.0, dot(-lightDirection, surfaceNormal));
}

LightResult _light(vec3 viewDirection, vec3 normal, vec3 lightVector) {

  vec3 lightDir = normalize(lightVector);

  //compute our diffuse & specular terms
  LightResult lr;
  if (uSpecular)
    lr.specular = _phongSpecular(lightDir, viewDirection, normal, uShininess);
  lr.diffuse = _lambertDiffuse(lightDir, normal);
  return lr;
}

void totalLight(
  vec3 modelPosition,
  vec3 normal,
  out vec3 totalDiffuse,
  out vec3 totalSpecular
) {

  totalSpecular = vec3(0.0);

  if (!uUseLighting) {
    totalDiffuse = vec3(1.0);
    return;
  }

  totalDiffuse = vec3(0.0);

  vec3 viewDirection = normalize(-modelPosition);

  for (int j = 0; j < 5; j++) {
    if (j < uDirectionalLightCount) {
      vec3 lightVector = (uViewMatrix * vec4(uLightingDirection[j], 0.0)).xyz;
      vec3 lightColor = uDirectionalDiffuseColors[j];
      vec3 specularColor = uDirectionalSpecularColors[j];
      LightResult result = _light(viewDirection, normal, lightVector);
      totalDiffuse += result.diffuse * lightColor;
      totalSpecular += result.specular * lightColor * specularColor;
    }

    if (j < uPointLightCount) {
      vec3 lightPosition = (uViewMatrix * vec4(uPointLightLocation[j], 1.0)).xyz;
      vec3 lightVector = modelPosition - lightPosition;

      //calculate attenuation
      float lightDistance = length(lightVector);
      float lightFalloff = 1.0 / (uConstantAttenuation + lightDistance * uLinearAttenuation + (lightDistance * lightDistance) * uQuadraticAttenuation);
      vec3 lightColor = lightFalloff * uPointLightDiffuseColors[j];
      vec3 specularColor = lightFalloff * uPointLightSpecularColors[j];

      LightResult result = _light(viewDirection, normal, lightVector);
      totalDiffuse += result.diffuse * lightColor;
      totalSpecular += result.specular * lightColor * specularColor;
    }

    if(j < uSpotLightCount) {
      vec3 lightPosition = (uViewMatrix * vec4(uSpotLightLocation[j], 1.0)).xyz;
      vec3 lightVector = modelPosition - lightPosition;

      float lightDistance = length(lightVector);
      float lightFalloff = 1.0 / (uConstantAttenuation + lightDistance * uLinearAttenuation + (lightDistance * lightDistance) * uQuadraticAttenuation);

      vec3 lightDirection = (uViewMatrix * vec4(uSpotLightDirection[j], 0.0)).xyz;
      float spotDot = dot(normalize(lightVector), normalize(lightDirection));
      float spotFalloff;
      if(spotDot < uSpotLightAngle[j]) {
        spotFalloff = 0.0;
      }
      else {
        spotFalloff = pow(spotDot, uSpotLightConc[j]);
      }
      lightFalloff *= spotFalloff;

      vec3 lightColor = uSpotLightDiffuseColors[j];
      vec3 specularColor = uSpotLightSpecularColors[j];

      LightResult result = _light(viewDirection, normal, lightVector);

      totalDiffuse += result.diffuse * lightColor * lightFalloff;
      totalSpecular += result.specular * lightColor * specularColor * lightFalloff;
    }
  }

  totalDiffuse *= diffuseFactor;
  totalSpecular *= specularFactor;
}
`;


let projectionVert = `
attribute vec3 aPosition;
attribute vec3 aNormal;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
uniform mat3 uNormalMatrix;

uniform mat4 uModelMatrix;
uniform mat4 uTexVMatrix;
uniform mat4 uTexPMatrix;

varying vec2 vTexCoord;
varying vec3 vDiffuseColor;
varying vec3 vSpecularColor;

void main(void) {
  vec4 positionVec4 = vec4(aPosition, 1.0);
	vec4 viewModelPosition = uModelViewMatrix * positionVec4; 
  gl_Position = uProjectionMatrix * viewModelPosition;

	vec4 texPosition = uTexPMatrix * uTexVMatrix * uModelMatrix * positionVec4;
	vTexCoord = texPosition.xy / texPosition.w * vec2(0.5, -0.5) + 0.5;		// ? : zで割るのかwで割るのか

	vec3 vertexNormal = normalize(vec3(uNormalMatrix * aNormal));
	totalLight(viewModelPosition.xyz, vertexNormal, vDiffuseColor, vSpecularColor);

	for (int i = 0; i < 8; i++) {
    if (i < uAmbientLightCount) {
      vDiffuseColor += uAmbientColor[i];
    }
  }
}
`;


let projectionFrag = `
precision highp float;

uniform vec4 uMaterialColor;
uniform sampler2D uTexture;		

varying vec2 vTexCoord;
varying vec3 vDiffuseColor;
varying vec3 vSpecularColor;

void main(void) {
	if (min(vTexCoord.x, vTexCoord.y) > 0.0 && max(vTexCoord.x, vTexCoord.y) < 1.0) {
		gl_FragColor = texture2D(uTexture, vTexCoord);
	} else {
  	gl_FragColor = uMaterialColor;
	}
	gl_FragColor.rgb = gl_FragColor.rgb * vDiffuseColor + vSpecularColor;
}
`;

